var e=e=>{if(!e)return null;if(Array.isArray(e.roles)){if(typeof e.roles[0]==`string`)return e.roles[0];if(e.roles[0]?.name)return e.roles[0].name}return e.role||null},t=t=>{switch(e(t)){case`super-admin`:case`admin`:return`/admin`;case`mall-owner`:case`supermarket-owner`:return`/owner`;case`delivery-person`:return`/delivery`;case`order-tracker`:return`/tracker`;default:return`/`}};export{t};